public class TypeErasureDemo<T extends Comparable<T>> {
    private T data;

    public TypeErasureDemo(T data) {
        this.data = data;
    }

    public T getData() {
        return data;
    }

    public static void main(String[] args) {
        TypeErasureDemo<String> demo = new TypeErasureDemo<>("Hello");
        String val = demo.getData(); // Compiler injects checkcast String here
    }
}
